+      patternType: PdfPatternTypes.Tiling,
+      stream: object,
+      paintType: paintType.value,
+      tilingType: tilingType.value,
+      bbox: bbox.value.value,
+      xStep: xStep.value,
+      yStep: yStep.value,
+      resources,
+      matrix: matrix.value.value,
+      warnings: [],
+    });
+  },
+
+  /**
+   * シェーディングと任意の拡張状態を取得する。
+   * @param dictionary - 種別2のパターン辞書
