+    }
+
+    const matrix = await PdfPattern.readMatrix(
+      fields.value.get("Matrix"),
+      resolveRef,
+    );
+    if (!matrix.ok) {
+      return matrix;
+    }
+
+    const object = fields.value.get("Shading");
+    const extended = fields.value.get("ExtGState");
