+   * @param resolveRef - 配列要素の参照解決関数
+   * @returns 省略時は単位行列、不正な配列は None、参照エラーは Err
+   */
+  async readMatrix(
+    value: PdfObject | undefined,
+    resolveRef: ResolveRef,
