+   * @returns 元のオブジェクトを保持した Unknown
+   */
+  unresolved(
+    object: PdfObject,
+    code: "PATTERN_INVALID" | "PATTERN_UNSUPPORTED",
+  ): PdfPattern {
+    return {
+      patternType: "Unknown",
+      object,
+      warnings: [
+        { code, message: "Invalid or unsupported pattern definition" },
+      ],
+    };
+  },
+} as const;

