+    if (!shadingType.some) {
+      return ok(PdfShading.unresolved(object, "SHADING_UNSUPPORTED"));
+    }
+
+    const fields = await ResourceParameters.resolve(
+      dictionary,
+      ["ColorSpace", "Background", "BBox"],
+      resolveRef,
+    );
